
 :root{
   --navy:#123a5c;--navy-deep:#0d2a44;--gold:#c9a24b;--gold-soft:#e6c877;
   --paper:#f7f4ec;--paper-warm:#fdfbf5;--ink:#1e2733;--ink-soft:#5a6675;
   --line:#e2dccd;--red:#d0454c;--green:#2f8f6b;
 }
 *{box-sizing:border-box;margin:0;padding:0;}
 html{scroll-behavior:smooth;}
 section[id]{scroll-margin-top:84px;}
 body{font-family:'Zen Kaku Gothic New',sans-serif;background:var(--paper);color:var(--ink);line-height:1.75;-webkit-font-smoothing:antialiased;}
 .maru{font-family:'Zen Maru Gothic',sans-serif;}
 /* ふりがな：オフのときだけ display:none で完全に消す（幅も取らない）。オンのときは display を一切上書きせず ルビ(ruby/rt) のネイティブ描画に任せる。
    ※iOS Safari(WebKit)は display:ruby / display:ruby-text という“値”を実装しておらず、値で切り替えるとスマホでルビが出ない。ネイティブ描画なら全ブラウザで出る。 */
 ruby rt{font-size:.52em;color:var(--navy);font-weight:700;user-select:none;white-space:nowrap;}
 body:not(.furigana) ruby rt{display:none;}
 /* オフのときrubyはただの文字と同じ挙動にする */
 ruby{ruby-align:center;}
 body:not(.furigana) ruby{display:inline;}
 body.furigana ruby{white-space:nowrap;line-height:1.15;}
 /* ふりがなオン時は本文の行の高さを一定にし、ルビが乗る行だけ広がる“ガタつき”を防ぐ */
 body.furigana{line-height:2.0;}
 /* 日本語の自然な行分割にまかせる（ルビ境界で切らない） */
 body{line-break:strict;word-break:normal;overflow-wrap:break-word;overflow-x:hidden;}
 p,li,h1,h2,h3,h4,.fi-detail,.insight,.sub,.lead,.hero p{line-break:strict;word-break:normal;overflow-wrap:normal;}
 /* ヘッダーのナビ・ロゴは折り返さない（実セレクタ） */
 header nav a,nav a{white-space:nowrap;}
 header a{white-space:nowrap;}
 .lead{max-width:36em;}

 header.site{position:sticky;top:0;z-index:100;background:rgba(247,244,236,.93);backdrop-filter:blur(8px);border-bottom:2px solid var(--navy);}
 body.dark header.site{background:rgba(21,23,29,.93);}
 .bar{max-width:1080px;margin:0 auto;padding:12px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;}
 .brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);}
 .logo-mark{width:42px;height:42px;flex:0 0 42px;border-radius:50%;overflow:hidden;display:block;}
 .logo-mark img{width:100%;height:100%;object-fit:cover;display:block;}
 /* ===== 中央の看板バナー ===== */
 .marutto-banner{max-width:920px;margin:8px auto 18px;border-radius:20px;overflow:hidden;box-shadow:0 10px 30px rgba(18,58,92,.18);border:1px solid var(--line);position:relative;}
 .marutto-banner img{width:100%;height:auto;display:block;}
 .marutto-banner::after{content:"";position:absolute;inset:0;box-shadow:inset 0 0 40px rgba(18,58,92,.06);pointer-events:none;}
 .logo-mark svg{width:100%;height:100%;display:block;}
 .logo-mark::before{content:"";width:13px;height:13px;border-radius:50%;background:var(--navy);}
 .logo-mark::after{content:"";position:absolute;width:6px;height:6px;border-radius:50%;background:var(--paper-warm);top:14px;left:16px;}
 .brand-txt b{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:20px;letter-spacing:.5px;display:block;line-height:1.15;}
 .brand-txt > span{font-size:11px;color:var(--ink-soft);letter-spacing:.5px;}
 .rgt{display:flex;align-items:center;gap:14px;}
 nav.menu{display:flex;gap:2px;}
 nav.menu a{font-size:13.5px;font-weight:700;color:var(--navy);text-decoration:none;padding:8px 12px;border-radius:30px;transition:.15s;}
 nav.menu a:hover{background:var(--navy);color:#fff;}
 /* 中間幅：ナビを詰める */
 @media(max-width:1460px){nav.menu a{padding:8px 9px;font-size:13px;}}
 @media(max-width:1680px){nav.menu a{padding:8px 6px;font-size:12px;} .brand-txt > span{display:none;}}
 @media(max-width:1320px){nav.menu a{padding:7px 4px;font-size:11.5px;}}
 @media(max-width:1180px){nav.menu{display:none;}}
 /* スマホ用メニュー */
 .burger{display:none;flex-direction:column;justify-content:center;gap:5px;width:42px;height:38px;background:#fff;border:1.5px solid var(--navy);border-radius:10px;cursor:pointer;padding:0 9px;}
 .burger span{display:block;height:2px;background:var(--navy);border-radius:2px;transition:.25s;}
 .burger.on span:nth-child(1){transform:translateY(7px) rotate(45deg);}
 .burger.on span:nth-child(2){opacity:0;}
 .burger.on span:nth-child(3){transform:translateY(-7px) rotate(-45deg);}
 .drawer{position:fixed;inset:0;background:rgba(18,58,92,.45);opacity:0;pointer-events:none;transition:.25s;z-index:80;}
 .drawer.on{opacity:1;pointer-events:auto;}
 .drawer-inner{position:absolute;top:0;right:0;width:min(84vw,320px);height:100%;background:var(--paper);box-shadow:-8px 0 30px rgba(0,0,0,.15);padding:78px 20px 24px;overflow-y:auto;transform:translateX(100%);transition:transform .28s cubic-bezier(.2,.8,.2,1);}
 .drawer.on .drawer-inner{transform:none;}
 .drawer-inner a{display:block;padding:15px 12px;font-weight:700;font-size:15px;color:var(--navy);text-decoration:none;border-bottom:1px solid var(--line);border-radius:8px;}
 .drawer-sec{padding:20px 12px 6px;font-size:11.5px;font-weight:900;color:var(--gold);letter-spacing:1.5px;}
 .drawer-sec:first-child{padding-top:6px;}
 .drawer-inner a{padding:12px 14px;font-size:14px;}
 .drawer-inner a:active{background:#fff;}
 @media(max-width:1180px){
   .burger{display:flex;}
   .furi-btn{font-size:11.5px;padding:6px 11px;}
   .rgt{gap:8px;}
 }
 @media(max-width:420px){
   .brand-txt > span{display:none;}
   .brand-txt b{font-size:16px;}
   .brand{gap:8px;}
   .furi-btn{padding:5px 8px;font-size:11px;}
   .burger{width:38px;height:34px;padding:0 8px;}
   .rgt{gap:6px;}
 }
 @media(max-width:380px){
   .brand-txt b{font-size:15px;}
   .logo-mark{transform:scale(.85);}
   .furi-btn{padding:5px 7px;font-size:10.5px;}
 }
 @media(max-width:365px){ .brand-txt{display:none;} }
 @media(max-width:340px){
   .brand-txt{display:none;}
   .furi-btn::before{content:"ふり ";}
 }
 .furi-btn{font-family:inherit;font-size:12.5px;font-weight:800;color:var(--navy);background:#fff;border:1.5px solid var(--navy);border-radius:30px;padding:7px 15px;cursor:pointer;transition:.15s;white-space:nowrap;}
 .furi-btn.on{background:var(--navy);color:#fff;}
 .furi-btn::before{content:"ふりがな ";font-weight:700;}

 .hero{max-width:1080px;margin:0 auto;padding:54px 20px 30px;}
 .hero-eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:var(--navy);background:#fff;border:1.5px solid var(--line);padding:6px 15px;border-radius:30px;margin-bottom:22px;}
 .hero-eyebrow .dot{width:8px;height:8px;border-radius:50%;background:var(--green);animation:pulse 2s infinite;}
 @keyframes pulse{50%{opacity:.35;}}
 .hero h1{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(32px,6vw,58px);line-height:1.3;letter-spacing:.5px;margin-bottom:20px;}
 .hero h1 .hl{position:relative;white-space:nowrap;}
 .hero h1 .hl::after{content:"";position:absolute;left:-2%;right:-2%;bottom:6%;height:32%;background:var(--gold-soft);opacity:.5;z-index:-1;border-radius:3px;}
 .hero p.lead{font-size:clamp(15px,2.4vw,18px);color:var(--ink-soft);max-width:640px;margin-bottom:30px;}
 .hero-cta{display:flex;gap:12px;flex-wrap:wrap;}
 .btn{font-family:inherit;font-size:15px;font-weight:700;text-decoration:none;padding:13px 26px;border-radius:30px;transition:.18s;cursor:pointer;border:2px solid transparent;display:inline-block;}
 .btn-main{background:var(--navy);color:#fff;}
 .btn-main:hover{background:var(--navy-deep);transform:translateY(-2px);}
 .btn-ghost{background:transparent;color:var(--navy);border-color:var(--navy);}
 .btn-ghost:hover{background:var(--navy);color:#fff;}

 section.block{max-width:1080px;margin:0 auto;padding:30px 20px;}
 .sec-head{display:flex;align-items:baseline;gap:12px;margin-bottom:20px;flex-wrap:wrap;}
 .sec-head h2{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:24px;letter-spacing:.5px;}
 .sec-head .en{font-size:12px;font-weight:700;color:var(--gold);letter-spacing:2px;text-transform:uppercase;}
 .sec-head .note{margin-left:auto;font-size:12.5px;color:var(--ink-soft);}

 .door .ico svg{display:block;}
 .doors{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;}
 @media(max-width:860px){.doors{grid-template-columns:1fr 1fr;}}
 @media(max-width:480px){.doors{grid-template-columns:1fr;}}
 .door{background:var(--paper-warm);border:1.5px solid var(--line);border-radius:16px;padding:24px 20px;text-decoration:none;color:var(--ink);transition:.18s;display:block;}
 .door:hover{transform:translateY(-3px);border-color:var(--navy);box-shadow:0 10px 24px rgba(18,58,92,.12);}
 .door .ico{width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:26px;margin-bottom:14px;background:var(--navy);color:#fff;}
 .door.c2 .ico{background:var(--red);}.door.c3 .ico{background:var(--green);}.door.c4 .ico{background:var(--gold);}
 .door h3{font-family:'Zen Maru Gothic',sans-serif;font-weight:700;font-size:17px;margin-bottom:6px;}
 .door p{font-size:12.5px;color:var(--ink-soft);line-height:1.55;}
 .door .go{margin-top:12px;font-size:12px;font-weight:700;color:var(--navy);}

 .gikai-wrap{background:var(--paper-warm);border:1.5px solid var(--line);border-left:6px solid var(--red);border-radius:16px;padding:24px;}
 .gikai-list{display:grid;grid-template-columns:1fr 1fr;gap:2px 22px;margin-top:6px;}
 @media(max-width:680px){.gikai-list{grid-template-columns:1fr;}}
 .gikai-item{display:flex;align-items:center;gap:11px;padding:11px 4px;border-bottom:1px solid var(--line);text-decoration:none;color:var(--ink);transition:.12s;}
 .gikai-item:hover{padding-left:8px;}
 .gikai-item .d{font-size:12px;color:var(--gold);font-weight:700;flex:0 0 auto;}
 .gikai-item .t{font-size:14px;font-weight:500;flex:1;}
 .gikai-item .arw{color:var(--line);font-size:18px;}
 .gikai-empty{color:var(--ink-soft);font-size:13.5px;padding:8px 0;}

 .money{display:grid;grid-template-columns:1.1fr 1fr;gap:28px;align-items:center;background:linear-gradient(135deg,var(--navy),var(--navy-deep));border-radius:20px;padding:34px;color:#fff;}
 @media(max-width:760px){.money{grid-template-columns:1fr;}}
 .money h2{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:26px;margin-bottom:12px;}
 .money p{font-size:14px;color:#cfe0ee;margin-bottom:8px;}
 .money .big{font-size:clamp(34px,7vw,52px);font-weight:900;font-family:'Zen Maru Gothic',sans-serif;color:var(--gold-soft);line-height:1;margin:14px 0 4px;}
 .money .big small{font-size:16px;color:#fff;font-weight:700;}
 .money-note{font-size:11.5px;color:#9fb8cd;margin-top:14px;}
 .bars{display:flex;flex-direction:column;gap:11px;}
 .bar-row .lab{display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:4px;color:#e8f0f7;}
 .bar-track{height:12px;background:rgba(255,255,255,.14);border-radius:10px;overflow:hidden;}
 .bar-fill{height:100%;border-radius:10px;background:var(--gold-soft);transition:width 1.2s cubic-bezier(.2,.8,.2,1);}

 /* シミュレーター */
 .sim{background:var(--paper-warm);border:1.5px solid var(--line);border-radius:20px;padding:30px;}
 .sim-grid{display:grid;grid-template-columns:340px 1fr;gap:28px;}
 @media(max-width:820px){.sim-grid{grid-template-columns:1fr;}}
 .sim-form .field{margin-bottom:18px;}
 .sim-form label{display:block;font-size:13px;font-weight:700;color:var(--ink);margin-bottom:7px;}
 .seg{display:inline-flex;background:#fff;border:1.5px solid var(--line);border-radius:12px;padding:3px;gap:2px;flex-wrap:wrap;}
 .seg button{font-family:inherit;font-size:13px;font-weight:700;color:var(--ink-soft);background:transparent;border:none;padding:8px 15px;border-radius:9px;cursor:pointer;transition:.15s;}
 .seg button.on{background:var(--navy);color:#fff;}
 .inc-input{display:flex;align-items:center;gap:8px;}
 .inc-input input{width:130px;font-family:inherit;font-size:17px;font-weight:700;padding:11px 13px;border:1.5px solid var(--line);border-radius:11px;background:#fff;}
 .inc-input input:focus{outline:none;border-color:var(--navy);}
 .stepper{display:flex;gap:6px;}
 .stepper button{font-family:inherit;font-size:12px;font-weight:700;color:var(--navy);background:#fff;border:1.5px solid var(--line);border-radius:20px;padding:5px 11px;cursor:pointer;}
 .stepper button:hover{background:var(--navy);color:#fff;}
 .num2{width:64px;font-family:inherit;font-size:15px;font-weight:700;padding:9px 11px;border:1.5px solid var(--line);border-radius:10px;background:#fff;text-align:center;}

 .sim-out{}
 .result-hero{background:linear-gradient(135deg,var(--navy),var(--navy-deep));border-radius:16px;padding:22px 24px;color:#fff;margin-bottom:16px;}
 .result-hero .k{font-size:13px;color:#cfe0ee;}
 .result-hero .v{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(28px,5vw,40px);color:var(--gold-soft);line-height:1.1;margin:2px 0 6px;}
 .result-hero .sub{font-size:12.5px;color:#cfe0ee;}
.result-hero .hero2{display:flex;gap:10px 26px;align-items:flex-end;flex-wrap:wrap;}
.result-hero .hero-cell{min-width:0;}
.result-hero .v.v-paid{font-size:clamp(21px,3.8vw,30px);color:#ffb3a3;}
 .breakdown{width:100%;border-collapse:collapse;font-size:13.5px;margin-top:4px;}
 .breakdown tr{border-bottom:1px solid var(--line);}
 .breakdown tr:last-child{border-bottom:none;}
 .breakdown td{padding:9px 2px;}
 .breakdown td.l{color:var(--ink-soft);}
 .breakdown td.l small{display:block;font-size:10.5px;color:#a49a86;}
 .breakdown td.r{text-align:right;font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap;}
 .breakdown tr.head td{font-weight:900;color:var(--navy);padding-top:6px;}
 .breakdown tr.sum td{border-top:2px solid var(--navy);padding-top:11px;font-weight:900;}
.breakdown tr.head.h-pay td{color:var(--red);}
.breakdown tr.head.h-ded td{color:#1d6fb8;}
.breakdown tr.r-pay td.r{color:var(--red);}
.breakdown tr.r-ded td.r{color:#1d6fb8;}
.breakdown tr.sum td.r{color:var(--red);}

 /* 金沢に届くお金 */
 .to-kanazawa{background:#fff;border:2px solid var(--gold);border-radius:16px;padding:22px 24px;margin-top:18px;}
 .to-kanazawa .tk-top{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:4px;}
 .to-kanazawa .tk-lbl{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:16px;color:var(--navy);}
 .to-kanazawa .tk-amt{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(24px,4vw,32px);color:var(--gold);}
 .to-kanazawa .tk-desc{font-size:12.5px;color:var(--ink-soft);margin-bottom:16px;}
 .use-list{display:flex;flex-direction:column;gap:9px;}
 .use-row .ul-lab{display:flex;justify-content:space-between;font-size:12.5px;margin-bottom:3px;}
 .use-row .ul-lab b{color:var(--navy);}
 .use-track{height:9px;background:var(--paper);border-radius:8px;overflow:hidden;}
 .use-fill{height:100%;border-radius:8px;background:var(--navy);}

 .tool{background:var(--paper-warm);border:1.5px solid var(--line);border-radius:16px;padding:26px;}
 .tool h3{font-family:'Zen Maru Gothic',sans-serif;font-weight:700;font-size:18px;margin-bottom:6px;display:flex;align-items:center;gap:9px;}
 .tool p.desc{font-size:13px;color:var(--ink-soft);margin-bottom:16px;}
 .search-box{display:flex;gap:8px;}
 .search-box input{flex:1;font-family:inherit;font-size:14px;padding:11px 14px;border:1.5px solid var(--line);border-radius:10px;background:#fff;}
 .search-box input:focus{outline:none;border-color:var(--navy);}
 .search-box button{font-family:inherit;font-size:14px;font-weight:700;color:#fff;background:var(--navy);border:none;padding:0 18px;border-radius:10px;cursor:pointer;}
 .chips{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px;}
 .chip{font-size:12px;font-weight:700;color:var(--navy);background:#fff;border:1.5px solid var(--line);padding:5px 12px;border-radius:30px;cursor:pointer;transition:.15s;}
 .chip:hover{background:var(--navy);color:#fff;}

 /* お金くわしく：タブと内訳 */
 .money-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px;}
 .money-tabs button{font-family:inherit;font-size:13.5px;font-weight:700;color:var(--navy);background:#fff;border:1.5px solid var(--line);border-radius:30px;padding:9px 18px;cursor:pointer;transition:.15s;}
 .money-tabs button.on{background:var(--navy);color:#fff;border-color:var(--navy);}
 .money-panel{display:none;}
 .money-panel.on{display:block;animation:fade .4s;}
 @keyframes fade{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}
 .flow-cols{display:grid;grid-template-columns:1fr 1fr;gap:16px;}
 @media(max-width:760px){.flow-cols{grid-template-columns:1fr;}}
 .flow-panel{background:var(--paper-warm);border:1.5px solid var(--line);border-radius:16px;padding:22px 24px;}
 .flow-panel h4{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:15px;margin-bottom:4px;}
 .flow-panel .sub{font-size:12px;color:var(--ink-soft);margin-bottom:16px;}
 .flow-item{margin-bottom:13px;cursor:default;}
.flow-name{flex:1;min-width:0;font-weight:700;}
.fi-item{margin-bottom:14px;}

 .flow-item .fi-lab{display:flex;justify-content:space-between;font-size:13px;margin-bottom:4px;gap:8px;}
 .flow-item .fi-lab .nm{font-weight:700;}
 .flow-item .fi-lab .amt{font-variant-numeric:tabular-nums;color:var(--ink-soft);white-space:nowrap;}
 .flow-track{height:11px;background:#eee;border-radius:8px;overflow:hidden;}
 .flow-fill{height:100%;border-radius:8px;transition:width 1s cubic-bezier(.2,.8,.2,1);}
 .flow-item .fi-detail{font-size:11.5px;color:var(--ink-soft);margin-top:5px;line-height:1.55;padding-left:2px;}
 .insight{background:#fff;border-left:5px solid var(--red);border-radius:0 12px 12px 0;padding:14px 18px;margin-top:16px;font-size:13px;line-height:1.7;}
 .insight b{color:var(--red);}
 .insight.blue{border-left-color:var(--navy);}
 .insight.blue b{color:var(--navy);}
 .gen-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px;}
 @media(max-width:620px){.gen-grid{grid-template-columns:1fr;}}
 .gen-card{background:var(--paper-warm);border:1.5px solid var(--line);border-radius:14px;padding:18px;text-align:center;}
 .gen-card .g-emoji{font-size:26px;}
 .gen-card .g-name{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14px;margin:4px 0;}
 .gen-card .g-pop{font-size:20px;font-weight:900;color:var(--navy);font-family:'Zen Maru Gothic',sans-serif;}
 .gen-card .g-pct{font-size:11.5px;color:var(--ink-soft);}
 .gen-bar{display:flex;height:34px;border-radius:10px;overflow:hidden;margin-bottom:8px;}
 .gen-seg{display:flex;align-items:center;justify-content:center;color:#fff;font-size:11px;font-weight:700;}

 /* 3つの柱・ステップ用ボックス */
 .pillar-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:6px;}
 @media(max-width:760px){.pillar-grid{grid-template-columns:1fr;}}
 .pillar{background:#fff;border:1.5px solid var(--line);border-top:5px solid var(--navy);border-radius:14px;padding:18px 16px;}
 .pillar .p-tag{font-size:11px;color:var(--gold);font-weight:700;letter-spacing:.05em;}
 .pillar .p-name{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14.5px;margin:6px 0 8px;line-height:1.4;}
 .pillar .p-desc{font-size:12px;color:var(--ink-soft);line-height:1.65;}
 .step-flow{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;align-items:stretch;}
 @media(max-width:760px){.step-flow{grid-template-columns:1fr;}}
 .step-box{background:#fff;border:1.5px solid var(--line);border-radius:14px;padding:16px;position:relative;}
 .step-box .s-num{display:inline-block;font-size:11px;font-weight:700;color:#fff;background:var(--navy);border-radius:20px;padding:3px 10px;}
 .step-box.now{border-color:var(--gold);border-width:2px;}
 .step-box.now .s-num{background:var(--gold);}
 .step-box.future{border-color:var(--green);}
 .step-box.future .s-num{background:var(--green);}
