 /* ===== カテゴリーカード（トップに並べる） ===== */
 .cat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:6px 0 8px;}
 @media(max-width:900px){.cat-grid{grid-template-columns:repeat(2,1fr);gap:12px;}}
 @media(max-width:430px){.cat-grid{grid-template-columns:repeat(2,1fr);gap:10px;}}
 .cat{background:#fff;border:1.5px solid var(--line);border-radius:18px;padding:16px 14px 14px;cursor:pointer;text-align:center;transition:.18s;position:relative;overflow:hidden;}
 /* ===== 映画ポスター風サムネ(has-thumbが付いたタイルのみ) ===== */
 .cat.has-thumb{background-image:var(--thumb);background-size:cover;background-position:center;background-repeat:no-repeat;border-color:transparent;}
 .cat.has-thumb::before{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(to bottom,rgba(10,22,40,.30) 0%,rgba(10,22,40,.55) 55%,rgba(10,22,40,.88) 100%);z-index:0;}
 .cat.has-thumb>*{position:relative;z-index:1;}
 .cat.has-thumb .cat-img{background:rgba(255,255,255,.92);box-shadow:0 2px 10px rgba(0,0,0,.35);}
 .cat.has-thumb h3{color:#fff;text-shadow:0 2px 8px rgba(0,0,0,.75),0 0 2px rgba(0,0,0,.6);}
 .cat.has-thumb p{color:rgba(255,255,255,.92);text-shadow:0 1px 6px rgba(0,0,0,.8);}
 .cat.has-thumb .cat-open{color:#ffd873;text-shadow:0 1px 5px rgba(0,0,0,.8);}
 .cat.has-thumb:hover{box-shadow:0 12px 30px rgba(18,58,92,.28);}
 .cat.has-thumb.on{border-color:var(--gold);border-width:2px;}
  .cat.has-thumb.on::before{background:linear-gradient(to bottom,rgba(10,22,40,.45) 0%,rgba(10,22,40,.70) 100%);}
 /* ===== 全部乗せ強化: 色帯・ボタン・ズーム・縁取り ===== */
 /* ①コーナー色の下辺ライン(--ccでJSが色を注入) */
 .cat.has-thumb::after{content:"";position:absolute;left:0;right:0;bottom:0;height:6px;background:var(--cc,transparent);z-index:2;box-shadow:0 -1px 6px var(--cc);}
 /* ③ホバー/タップで背景サムネがふわっとズーム */
 .cat.has-thumb{transition:transform .5s cubic-bezier(.22,.61,.36,1),box-shadow .3s ease;}
 .cat.has-thumb:hover{transform:translateY(-3px) scale(1.035);z-index:5;transition:transform .5s cubic-bezier(.22,.61,.36,1),box-shadow .3s ease;}
 /* ④アイコン白丸をコーナー色で縁取り */
 .cat.has-thumb .cat-img{border:2.5px solid var(--cc,#fff);}
 /* ②「ひらく」を金色の角丸ボタン風に */
 .cat.has-thumb .cat-open{display:inline-block;margin-top:9px;padding:3px 14px;border-radius:20px;background:rgba(255,216,115,.16);border:1px solid rgba(255,216,115,.55);backdrop-filter:blur(2px);}
 .cat.has-thumb:not(.on) .cat-open::before{content:"▼ ひらく";}
 .cat.has-thumb.on .cat-open{background:rgba(255,216,115,.28);}
 .cat:hover{transform:translateY(-3px);box-shadow:0 10px 26px rgba(18,58,92,.10);border-color:var(--navy);}
 .cat.on{border-color:var(--navy);border-width:2px;background:var(--paper-warm);}
 .cat .cat-img{width:74px;height:74px;margin:0 auto 10px;border-radius:50%;background:var(--paper-warm);display:flex;align-items:center;justify-content:center;overflow:hidden;color:var(--navy);}
 .cat .cat-img img{width:100%;height:100%;object-fit:cover;display:block;}
 .cat .cat-img svg{width:38px;height:38px;}
 .cat h3{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14px;line-height:1.4;margin-bottom:4px;color:var(--navy);}
 .cat p{font-size:11px;color:var(--ink-soft);line-height:1.5;}
 .cat .cat-open{margin-top:8px;font-size:11px;font-weight:800;color:var(--gold);}
 .cat.on .cat-open::before{content:"▲ とじる";}
 .cat:not(.on) .cat-open::before{content:"▼ ひらく";}
 @media(max-width:430px){
   .cat{padding:12px 8px 10px;border-radius:14px;}
   .cat .cat-img{width:58px;height:58px;margin-bottom:7px;}
   .cat .cat-img svg{width:30px;height:30px;}
   .cat h3{font-size:12.5px;}
   .cat p{display:none;}
 }
