 .xlink{color:var(--navy);font-weight:800;text-decoration:underline;text-decoration-style:dotted;text-underline-offset:3px;}
 .xlink:hover{color:var(--gold);}
 .qwrap .xlink,.qexp .xlink{color:var(--gold-soft);}

 .catg{grid-column:1/-1;display:flex;align-items:baseline;gap:10px;margin:20px 2px 2px;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;color:var(--navy);font-size:15.5px;}
 .catg::after{content:"";flex:1;height:1.5px;background:var(--line);}
 .catg small{font-weight:600;color:var(--ink-soft);font-size:11px;flex:0 0 auto;}
 .catg:first-child{margin-top:0;}
 .catg span ruby rt{font-size:8px;}

.maeda-tree{display:flex;flex-direction:column;align-items:center;margin:14px 0 4px;}
.mt-node{background:var(--cream,#fbf7ef);border:1.5px solid rgba(20,40,80,.18);border-radius:12px;padding:9px 15px;text-align:center;max-width:340px;width:100%;box-sizing:border-box;transition:transform .15s,box-shadow .15s;}
.mt-node[onclick]{cursor:pointer;}
.mt-node[onclick]:hover{transform:translateY(-2px);box-shadow:0 4px 14px rgba(20,40,80,.14);}
.mt-node .mt-gen{display:inline-block;font-size:11px;font-weight:700;color:#fff;background:var(--navy,#1b3a6b);border-radius:20px;padding:1px 10px;margin-bottom:3px;}
.mt-node b{display:block;font-size:16px;color:var(--navy,#1b3a6b);line-height:1.4;}
.mt-node small{display:block;font-size:11px;color:#8a8172;margin-top:1px;}
.mt-node em{display:block;font-style:normal;font-size:12px;color:#5a5348;margin-top:4px;line-height:1.6;}
.mt-star{border-color:var(--gold,#c9a84a);border-width:2px;background:linear-gradient(180deg,#fffdf6,#faf3e0);}
.mt-star .mt-gen{background:var(--gold,#c9a84a);}
.mt-star b::after{content:" ★";color:var(--gold,#c9a84a);font-size:12px;}
.mt-line{width:2px;height:16px;background:rgba(20,40,80,.25);}
.mt-line.mt-adopt,.mt-line.mt-multi{height:auto;width:auto;background:none;font-size:10.5px;color:#a89a5e;padding:2px 0;border-left:2px dotted rgba(20,40,80,.3);padding-left:0;}
.mt-line.mt-adopt span,.mt-line.mt-multi span{display:inline-block;background:rgba(201,168,74,.13);border-radius:10px;padding:1px 9px;}
.mt-siblings{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;max-width:360px;}
.mt-node.mt-sm{padding:6px 10px;max-width:80px;}
.mt-node.mt-sm b{font-size:13px;}
.mt-node.mt-sm .mt-gen{font-size:10px;padding:0 7px;}
.hero h1.hero-big{font-size:clamp(44px,10vw,84px);line-height:1.2;letter-spacing:1px;}

/* ===== 金沢まるっと10問クイズ ===== */
#qzBody{max-width:520px;margin:0 auto;}
.qz-start{text-align:center;padding:10px 4px;}
.qz-hero-emoji{font-size:52px;line-height:1;margin:6px 0 4px;}
.qz-title-big{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:22px;color:var(--navy);margin:6px 0;}
.qz-lead{font-size:14px;color:var(--ink-soft,#5a5348);line-height:1.9;margin:8px 0 16px;}
.qz-streak{display:inline-block;background:#fff3e0;color:#c8621b;font-weight:700;font-size:13px;border-radius:20px;padding:5px 16px;margin-bottom:14px;border:1.5px solid #f2c795;}
.qz-note{font-size:11px;color:#9a917f;margin-top:12px;}
.qz-sub{font-size:14px;color:var(--navy);font-weight:700;margin:12px 0;}

.qz-btn{display:block;width:100%;box-sizing:border-box;border:none;border-radius:14px;padding:15px;font-size:16px;font-weight:700;cursor:pointer;margin:9px 0;font-family:inherit;transition:transform .12s,box-shadow .12s;}
.qz-btn:active{transform:scale(.98);}
.qz-btn-main{background:var(--navy,#1b3a6b);color:#fff;font-size:18px;box-shadow:0 4px 14px rgba(27,58,107,.28);}
.qz-btn-share{background:var(--gold,#c9a84a);color:#fff;box-shadow:0 4px 12px rgba(201,168,74,.3);}
.qz-btn-next{background:var(--navy,#1b3a6b);color:#fff;margin-top:14px;}
.qz-btn-ghost{background:transparent;color:var(--ink-soft,#6a6252);border:1.5px solid var(--line,#e0dccf);font-size:14px;font-weight:600;padding:12px;}

.qz-done-badge{display:inline-block;background:#e6f4ea;color:#2e7d4f;font-weight:700;font-size:13px;border-radius:20px;padding:6px 18px;margin-bottom:16px;border:1.5px solid #a9dcbc;}

/* プレイ画面 */
.qz-play{padding:4px;}
.qz-progress{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:var(--ink-soft,#6a6252);font-weight:700;margin-bottom:8px;gap:8px;}
.qz-cat{background:var(--cream,#f3ede0);border-radius:12px;padding:2px 10px;color:var(--navy);font-size:11px;}
.qz-timer{color:var(--gold,#b8963c);min-width:52px;text-align:right;font-variant-numeric:tabular-nums;}
.qz-bar{height:6px;background:#eee7d8;border-radius:6px;overflow:hidden;margin-bottom:16px;}
.qz-bar-fill{height:100%;background:linear-gradient(90deg,var(--gold,#c9a84a),var(--navy,#1b3a6b));border-radius:6px;transition:width .3s;}
.qz-question{font-family:'Zen Maru Gothic',sans-serif;font-weight:700;font-size:18px;line-height:1.6;color:var(--navy,#1b3a6b);background:var(--cream,#faf6ec);border-radius:14px;padding:18px;margin-bottom:16px;text-align:center;}
.qz-opts{display:flex;flex-direction:column;gap:10px;}
.qz-opt{background:#fff;border:2px solid var(--line,#e0dccf);border-radius:13px;padding:15px;font-size:16px;font-weight:600;color:var(--ink,#2a2620);cursor:pointer;text-align:left;font-family:inherit;transition:all .12s;}
.qz-opt:hover:not(:disabled){border-color:var(--navy,#1b3a6b);background:#fafaff;}
.qz-opt:active:not(:disabled){transform:scale(.98);}
.qz-opt:disabled{cursor:default;}
.qz-opt.qz-correct{border-color:#2e9e5b;background:#e9f7ee;color:#1e7d43;}
.qz-opt.qz-wrong{border-color:#d64a4a;background:#fdeaea;color:#b53131;}

.qz-explain{margin-top:8px;}
.qz-ex-head{font-weight:800;font-size:17px;text-align:center;margin:14px 0 8px;}
.qz-ex-head.ok{color:#2e9e5b;}
.qz-ex-head.ng{color:#d64a4a;}
.qz-ex-body{font-size:14px;line-height:1.85;color:var(--ink-soft,#5a5348);background:var(--cream,#faf6ec);border-radius:12px;padding:14px;}

/* 結果カード（シェア映え） */
.qz-fanfare{font-size:46px;text-align:center;margin:4px 0;}
.qz-result-card{background:linear-gradient(155deg,#1b3a6b,#2a5495);border-radius:20px;padding:24px 20px;color:#fff;text-align:center;box-shadow:0 10px 30px rgba(27,58,107,.32);margin:6px auto 14px;max-width:340px;position:relative;overflow:hidden;}
.qz-result-card::before{content:"";position:absolute;top:-40%;right:-30%;width:200px;height:200px;background:radial-gradient(circle,rgba(201,168,74,.28),transparent 70%);}
.qz-rc-head{font-size:12px;letter-spacing:1px;opacity:.85;font-weight:700;position:relative;}
.qz-rc-date{font-size:11px;opacity:.7;margin-top:2px;position:relative;}
.qz-rc-emoji{font-size:48px;margin:8px 0 2px;position:relative;}
.qz-rc-score{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:54px;line-height:1;position:relative;}
.qz-rc-score span{font-size:22px;margin-left:3px;}
.qz-rc-title{font-family:'Zen Maru Gothic',sans-serif;font-weight:700;font-size:20px;color:#f0d488;margin-top:8px;position:relative;}
.qz-rc-detail{font-size:13px;opacity:.9;margin-top:6px;position:relative;}
.qz-rc-streak{display:inline-block;background:rgba(255,255,255,.16);border-radius:16px;padding:3px 14px;font-size:12px;font-weight:700;margin-top:10px;position:relative;}

/* トースト */
.qz-toast{position:fixed;bottom:30px;left:50%;transform:translateX(-50%) translateY(20px);background:var(--navy,#1b3a6b);color:#fff;padding:12px 24px;border-radius:30px;font-size:14px;font-weight:700;opacity:0;pointer-events:none;transition:all .3s;z-index:9999;box-shadow:0 6px 20px rgba(0,0,0,.25);}
.qz-toast.show{opacity:1;transform:translateX(-50%) translateY(0);}

/* ===== ランキング ===== */
.qz-btn-rank{background:var(--gold,#c9a84a);color:#fff;box-shadow:0 4px 12px rgba(201,168,74,.3);}
.qz-btn-rankview{background:#fff;color:var(--navy,#1b3a6b);border:2px solid var(--navy,#1b3a6b);font-size:15px;}
.qz-name-input{width:100%;box-sizing:border-box;border:2px solid var(--line,#e0dccf);border-radius:12px;padding:14px;font-size:18px;text-align:center;font-family:inherit;margin:6px 0;}
.qz-name-input:focus{outline:none;border-color:var(--navy,#1b3a6b);}
.qz-name-msg{font-size:13px;font-weight:700;min-height:20px;margin:4px 0 10px;}
.qz-name-msg.err{color:#d64a4a;}
/* ランキングカード（シェア映え） */
.qz-rank-card{background:linear-gradient(160deg,#faf6ec,#fff);border:2px solid var(--gold,#c9a84a);border-radius:18px;padding:18px 14px;margin:6px auto 14px;max-width:360px;box-shadow:0 8px 26px rgba(201,168,74,.2);}
.qz-rank-title{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:17px;color:var(--navy,#1b3a6b);text-align:center;margin-bottom:12px;}
.qz-rank-list{display:flex;flex-direction:column;gap:5px;max-height:420px;overflow-y:auto;}
.qz-rank-row{display:flex;align-items:center;gap:10px;background:#fff;border-radius:10px;padding:9px 12px;border:1.5px solid #eee7d8;}
.qz-rank-row.top3{background:linear-gradient(90deg,#fffdf5,#fff);border-color:#f0dca0;}
.qz-rank-row.me{background:#eef4ff;border-color:var(--navy,#1b3a6b);border-width:2px;}
.qz-rank-pos{font-weight:800;font-size:15px;min-width:38px;text-align:center;color:var(--navy,#1b3a6b);}
.qz-rank-row.top3 .qz-rank-pos{font-size:20px;}
.qz-rank-name{flex:1;font-weight:700;font-size:15px;color:var(--ink,#2a2620);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.qz-rank-you{background:var(--navy,#1b3a6b);color:#fff;font-size:10px;border-radius:8px;padding:1px 6px;margin-left:4px;vertical-align:middle;}
.qz-rank-score{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:19px;color:var(--gold,#b8963c);}
.qz-rank-score small{font-size:11px;font-weight:700;margin-left:1px;}
.qz-rank-foot{text-align:center;font-size:11px;color:#9a917f;margin-top:12px;font-weight:700;}
.qz-rank-empty{text-align:center;color:#9a917f;font-size:14px;line-height:2;padding:24px 0;}

/* ===== 補助金・助成金ガイド ===== */
.subsidy-caution{background:#fff5ec;border:1.5px solid #f2c795;border-radius:12px;padding:11px 14px;font-size:12.5px;line-height:1.7;color:#a5531b;margin-bottom:16px;}
#subsidyBody{max-width:600px;margin:0 auto;}
.sub-cat{margin-bottom:22px;}
.sub-cat-head{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:17px;color:var(--navy);padding:9px 13px;background:var(--cream,#faf6ec);border-radius:11px;margin-bottom:10px;}
.sub-cat-head small{display:block;font-size:11px;color:#9a917f;font-weight:400;margin-top:2px;}
.sub-item{background:#fff;border:1.5px solid var(--line,#e0dccf);border-radius:12px;padding:13px 15px;margin-bottom:9px;}
.sub-item-top{display:flex;align-items:center;gap:8px;margin-bottom:5px;flex-wrap:wrap;}
.sub-level{color:#fff;font-size:11px;font-weight:700;border-radius:7px;padding:2px 9px;flex-shrink:0;}
.sub-name{font-weight:800;font-size:14.5px;color:var(--ink,#2a2620);line-height:1.4;}
.sub-org{font-size:11.5px;color:#8a8172;margin-bottom:6px;}
.sub-desc{font-size:13px;line-height:1.8;color:var(--ink-soft,#5a5348);margin-bottom:9px;}
.sub-link{display:inline-block;font-size:13px;font-weight:700;color:var(--navy,#1b3a6b);text-decoration:none;border:1.5px solid var(--navy,#1b3a6b);border-radius:9px;padding:6px 14px;transition:all .12s;}
.sub-link:active{transform:scale(.98);}

.rights-divider{display:flex;align-items:center;text-align:center;margin:26px 0 16px;}
.rights-divider::before,.rights-divider::after{content:"";flex:1;height:1.5px;background:linear-gradient(90deg,transparent,var(--gold,#c9a84a),transparent);}
.rights-divider span{padding:0 14px;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:15px;color:var(--gold,#b8963c);white-space:nowrap;}

/* ===== 政務活動費パート ===== */
.seimu-facts{display:flex;gap:12px;margin:16px 0;}
.seimu-fact{flex:1;background:linear-gradient(155deg,#eaf4fc,#dbeaf8);border:1.5px solid #a9cded;border-radius:14px;padding:16px 10px;text-align:center;}
.seimu-fact-num{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:30px;color:#1a5a8a;line-height:1.1;}
.seimu-fact-num span{font-size:15px;margin-left:2px;}
.seimu-fact-label{font-size:11px;color:#4a6a85;margin-top:6px;line-height:1.5;font-weight:700;}



/* ===== 追加部品(2026-08-09移植): 表示バー/診断/共有/用語/トレマップ/印刷/鮮度 ===== */
.vb2{font-family:inherit;font-size:12px;font-weight:800;color:var(--navy);background:#fff;border:1.5px solid var(--line);border-radius:30px;padding:7px 11px;cursor:pointer;white-space:nowrap;transition:.15s;}
.vb2.on{background:var(--navy);color:#fff;}
body.dark{--paper:#15171d;--paper-warm:#1d2027;--ink:#e8e6e1;--ink-soft:#a9a49b;--line:#3a3e48;--navy:#8fb4dc;--gold:#d4b467;}
body.dark .burger,body.dark .cat,body.dark .chip,body.dark .drawer-inner a:active,body.dark .furi-btn,body.dark .hero-eyebrow,body.dark .inc-input input,body.dark .insight,body.dark .jsearch,body.dark .jtab,body.dark .layer-row,body.dark .money-tabs button,body.dark .num2,body.dark .pillar,body.dark .qc,body.dark .qz-btn-rankview,body.dark .qz-opt,body.dark .qz-rank-row,body.dark .receive-box,body.dark .search-box input,body.dark .seg,body.dark .soudan-card,body.dark .step-box,body.dark .stepper button,body.dark .sub-item,body.dark .to-kanazawa,body.dark .vchip,body.dark .why-box,body.dark details.acc,body.dark details.jgo[open]{background:#232833;}
body.dark [style*="background:#fff"]{background:#232833!important;}
body.dark img{opacity:.88;}
body.dark .cat.has-thumb{background:var(--thumb) center/cover no-repeat;}
.diag-wrap{background:#fff;border:1.5px solid var(--line);border-radius:18px;padding:16px 16px 12px;margin:14px 0;}
body.dark .diag-wrap{background:#232833;}
.diag-wrap h3{font-size:15.5px;color:var(--navy);margin-bottom:2px;}
.diag-wrap .dsub{font-size:12.5px;color:var(--ink-soft);margin-bottom:10px;}
.diag-chips{display:flex;flex-wrap:wrap;gap:8px;}
.diag-chip{font-family:inherit;font-size:13px;font-weight:700;color:var(--navy);background:var(--paper);border:1.5px solid var(--line);border-radius:30px;padding:8px 13px;cursor:pointer;transition:.13s;}
.diag-chip.sel{background:var(--navy);color:#fff;border-color:var(--navy);}
.diag-out{margin-top:10px;}
.diag-card{display:block;border:1px solid var(--line);border-left:4px solid var(--gold);border-radius:10px;padding:8px 12px;margin:7px 0;background:var(--paper-warm);text-decoration:none;color:var(--ink);}
.diag-card b{font-size:14px;color:var(--navy);}
.diag-card small{color:var(--ink-soft);display:block;font-size:12px;}
.share-row{display:flex;gap:8px;margin:8px 0 2px;flex-wrap:wrap;}
.share-btn{font-family:inherit;font-size:12px;font-weight:700;border:1.5px solid var(--line);background:#fff;color:var(--navy);border-radius:20px;padding:5px 12px;cursor:pointer;}
body.dark .share-btn{background:#232833;}
.share-btn:active{background:var(--navy);color:#fff;}
#shareToast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--navy);color:#fff;border-radius:999px;padding:8px 18px;font-size:13px;opacity:0;pointer-events:none;transition:opacity .3s;z-index:200;}
#shareToast.show{opacity:1;}
.term{border-bottom:1.5px dashed var(--gold);cursor:help;}
#termPop{position:fixed;z-index:150;max-width:min(330px,86vw);background:#fff;color:var(--ink);border:1.5px solid var(--navy);border-radius:12px;padding:10px 13px;font-size:13px;line-height:1.65;box-shadow:0 8px 22px rgba(13,42,68,.22);display:none;}
body.dark #termPop{background:#232833;}
#termPop b{color:var(--navy);}
#termPop .tp-x{float:right;border:none;background:none;color:var(--ink-soft);font-size:15px;padding:0 0 0 8px;cursor:pointer;}
#tmWrap svg{width:100%;height:auto;display:block;border-radius:12px;}
.tm-cell{stroke:var(--paper);stroke-width:2;}
.tm-t{font-size:13px;fill:#fff;font-weight:800;pointer-events:none;}
.tm-s{font-size:11px;fill:rgba(255,255,255,.9);pointer-events:none;}
.tm-legend{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:8px;font-size:12px;color:var(--ink-soft);}
.tm-legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:4px;}
.fresh-badge{display:inline-block;font-size:11.5px;font-weight:700;color:var(--ink-soft);background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:2px 10px;margin:4px 0 8px;}
.cat-print{font-family:inherit;font-size:12px;font-weight:700;border:1.5px solid var(--line);background:#fff;color:var(--navy);border-radius:20px;padding:6px 13px;cursor:pointer;margin-right:8px;}
body.dark .cat-print{background:#232833;}
.print-head-x{display:none;}
@media print{
  body.printing *{visibility:hidden!important;}
  body.printing .print-target,body.printing .print-target *{visibility:visible!important;}
  body.printing .print-target{position:absolute!important;left:0;top:0;width:100%;}
  body.printing .print-target .no-print,body.printing .print-target button,body.printing .print-target .cat-print,body.printing .print-target .cat-close,body.printing .print-target .share-row{display:none!important;}
  body.printing .print-target .print-head-x{display:block!important;border-bottom:3px double #000;padding-bottom:6px;margin-bottom:10px;font-size:11pt;}
}
@media(max-width:430px){.vb2{padding:6px 8px;font-size:11px;}}
