.cat.cfold-hide{display:none!important;}

.gloss{border-bottom:1.5px dotted var(--gold,#c9a24b);cursor:pointer;position:relative;}
.gloss-pop{position:fixed;left:12px;right:12px;bottom:14px;z-index:999;width:auto;max-width:520px;margin:0 auto;background:var(--paper,#fff);border:1.5px solid var(--gold,#c9a24b);border-radius:10px;box-shadow:0 6px 22px rgba(0,0,0,.35);padding:10px 12px;font-size:13px;line-height:1.6;color:var(--ink,#333);font-weight:400;text-align:left;white-space:normal;}
