.rn-floor.rn-up .rn-small{font-size:12.5px;color:var(--muted);margin-top:4px;}
.rn-pillars{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;}
.rn-pil{border-radius:12px;padding:14px 8px;text-align:center;color:#fff;}
