#kdata .rn-stat-em{font-size:22px;line-height:1;}
#kdata .rn-stat-lb{display:block;font-size:12px;color:var(--muted);font-weight:700;margin-top:5px;}
#kdata .rn-stat-nm{display:block;font-size:18px;font-weight:900;color:var(--ink);font-family:'Zen Maru Gothic',sans-serif;margin-top:1px;}
