#tetsudo .rn-use-head .rn-nm{min-width:0;}
#tetsudo .rn-talk1 .rn-tx{min-width:0;}
#tetsudo .rn-mini .rn-m{display:block;}
#tetsudo .rn-mini .rn-m .rn-mk{float:left;margin-right:8px;}
#tetsudo .rn-mini .rn-m::after{content:"";display:table;clear:both;}



