/* 実機フィードバック修正2 2026-08-16 */
#runquest{-webkit-text-size-adjust:100%;text-size-adjust:100%;overflow-wrap:normal;word-break:normal;line-break:strict;max-width:100%;box-sizing:border-box;overflow-x:hidden;}
#runquest ruby{ruby-align:center;ruby-position:over;-webkit-ruby-position:before;vertical-align:baseline;line-height:1!important;}
#runquest ruby rt{font-family:'Zen Kaku Gothic New',sans-serif;font-weight:700;font-size:.52em!important;line-height:1!important;letter-spacing:0;color:var(--muted);white-space:nowrap;user-select:none;pointer-events:none;vertical-align:baseline;margin-bottom:0;}
@supports (text-box-edge: cap alphabetic){#runquest ruby rt{text-box-trim:trim-both;text-box-edge:cap alphabetic;}}
body:not(.furigana) #runquest ruby rt{display:none!important;}
#runquest p,#runquest .rn-intro,#runquest .rn-qh,#runquest .rn-opt,#runquest .rn-tx,#runquest .rn-use-body,#runquest .rn-pd,#runquest .rn-bld-note{line-height:2.1!important;}
/* クイズ見出し: flex解除して問題文を普通に折り返す(1文字改行を止める) */
#runquest .rn-quiz .rn-qh{display:block;}
#runquest .rn-quiz .rn-qh .rn-qd{float:left;margin:2px 9px 0 0;}
#runquest .rn-quiz .rn-qh::after{content:"";display:table;clear:both;}
/* 選択肢: 同じくflex解除 */
#runquest .rn-opt{display:block;}
#runquest .rn-opt .rn-k{float:left;margin:1px 12px 0 0;}
#runquest .rn-opt::after{content:"";display:table;clear:both;}
#runquest>h2.rn-maru,#runquest>h2.maru{font-size:clamp(30px,7.5vw,42px)!important;line-height:1.2;margin:6px 0 2px;color:var(--ink);white-space:normal;overflow-wrap:break-word;word-break:normal;max-width:100%;}
#runquest .rn-intro{font-size:15px;}

/* 精査2巡目: 残りのflex箇所もルビ長文で縮まず崩れる→対処 */
#runquest .rn-use-head .rn-nm{min-width:0;}
#runquest .rn-talk1 .rn-tx{min-width:0;}
#runquest .rn-mini .rn-m{display:block;}
#runquest .rn-mini .rn-m .rn-mk{float:left;margin-right:8px;}
#runquest .rn-mini .rn-m::after{content:"";display:table;clear:both;}

/* ===== 金沢ランニングクエスト ===== */
#runquest .rq-stat{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin:18px 0 10px}
#runquest .rq-stat div{background:var(--card);border:2px solid var(--line);border-radius:14px;padding:10px 6px;text-align:center}
#runquest .rq-stat b{display:block;font-size:26px;color:var(--navy);font-family:'Zen Maru Gothic',sans-serif}
#runquest .rq-stat span{font-size:11px;color:var(--ink-soft)}
#runquest .rq-barlab{display:flex;justify-content:space-between;font-size:12px;color:var(--ink-soft);font-weight:700}
#runquest .rq-bar{height:16px;background:var(--card);border:2px solid var(--line);border-radius:999px;overflow:hidden;margin:4px 0 8px}
#runquest .rq-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#43a047,var(--gold));transition:width .6s}
#runquest .rq-next{font-size:13.5px;color:var(--ink-soft);margin-bottom:10px}
#runquest .rq-next b{color:var(--ink)}
#runquest #rq-map{width:100%;height:auto;display:block;background:var(--paper-warm);border:2px solid var(--line);border-radius:14px}
#runquest .rq-leg{display:flex;gap:10px;flex-wrap:wrap;font-size:11px;color:var(--ink-soft);margin-top:8px}
#runquest .rq-leg i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:3px;vertical-align:middle}
#runquest .rq-note{font-size:12px;color:var(--ink-soft);margin-top:8px;line-height:1.7}
#runquest .rq-list{list-style:none;padding:0;margin:8px 0 0}
#runquest .rq-list li{display:grid;grid-template-columns:44px 1fr auto auto;gap:8px;align-items:center;padding:8px 6px;border-bottom:1px solid var(--line);font-size:13px}
#runquest .rq-lvn{font-weight:900;color:var(--ink-soft);font-family:'Zen Maru Gothic',sans-serif}
#runquest .rq-done .rq-lvn{color:var(--gold)}
#runquest .rq-now{background:rgba(201,162,75,.12);border-radius:10px}
#runquest .rq-nm{font-weight:700}
#runquest .rq-nm i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:5px}
#runquest .rq-nm small{display:block;font-weight:400;color:var(--ink-soft);font-size:11px}
#runquest .rq-need{font-size:11px;color:var(--ink-soft);text-align:right;line-height:1.4}
#runquest .rq-st{font-size:11px;padding:3px 9px;border-radius:999px;background:var(--line);color:var(--ink-soft);white-space:nowrap}
#runquest .rq-done .rq-st{background:#43a047;color:#fff}
#runquest .rq-open .rq-st{background:transparent;border:2px solid var(--gold);color:var(--ink)}
#runquest .rq-now .rq-st{background:var(--gold);color:#fff}



