.rn-term-pop{position:fixed;left:12px;right:12px;bottom:14px;margin:0 auto;max-width:520px;background:var(--paper,#fff);border:1.5px solid var(--gold,#c9a24b);color:var(--ink,#333);border-radius:10px;padding:14px 16px 15px;box-shadow:0 6px 22px rgba(0,0,0,.35);z-index:999;font-size:14px;line-height:1.8;animation:rn-pop .3s ease;}
