#money p,#money .rn-intro,#money .rn-qh,#money .rn-opt,#money .rn-tx,#money .rn-use-body,#money .rn-pd,#money .rn-bld-note{line-height:2.1!important;}
/* クイズ見出し: flex解除して問題文を普通に折り返す(1文字改行を止める) */
#money .rn-quiz .rn-qh{display:block;}
#money .rn-quiz .rn-qh .rn-qd{float:left;margin:2px 9px 0 0;}
#money .rn-quiz .rn-qh::after{content:"";display:table;clear:both;}
/* 選択肢: 同じくflex解除 */
#money .rn-opt{display:block;}
#money .rn-opt .rn-k{float:left;margin:1px 12px 0 0;}
#money .rn-opt::after{content:"";display:table;clear:both;}
#money>h2.rn-maru,#money>h2.maru{font-size:clamp(30px,7.5vw,42px)!important;line-height:1.2;margin:6px 0 2px;color:var(--ink);white-space:normal;overflow-wrap:break-word;word-break:normal;max-width:100%;}
#money .rn-intro{font-size:15px;}

/* 精査2巡目: 残りのflex箇所もルビ長文で縮まず崩れる→対処 */
#money .rn-use-head .rn-nm{min-width:0;}
#money .rn-talk1 .rn-tx{min-width:0;}
#money .rn-mini .rn-m{display:block;}
#money .rn-mini .rn-m .rn-mk{float:left;margin-right:8px;}
#money .rn-mini .rn-m::after{content:"";display:table;clear:both;}



#kane{
  --paper:#FBF5E9; --card:#FFFFFF; --ink:#22344F; --ink-2:#465b78; --muted:#7c8698;
  --navy:#1f3a63; --gold:#E0A93E; --gold-d:#b07c1c; --line:#ece3d2; --sky:#eaf3fc; --green:#2f8f6b;
  --r1:#2E6DB4; --r2:#2f8f6b; --r3:#d99a2b;
  --m1:#C2542F; --m2:#2E6DB4; --m3:#6E8B3D; --m4:#A379CE; --m5:#37A9A0;
}

  body.dark #kane{
    --paper:#12151c; --card:#1b1f29; --ink:#ece4d6; --ink-2:#c3bcae; --muted:#8b8577;
    --navy:#9dc0e8; --gold:#eac266; --gold-d:#eac266; --line:#2c313d; --sky:#1e2836; --green:#57b892;
    --r1:#4E86B6; --r2:#57b892; --r3:#e0b25a;
    --m1:#db6e45; --m2:#4E86B6; --m3:#8caa55; --m4:#8e77a7; --m5:#5fa69f;
  }

#kane{background:var(--paper);color:var(--ink);font-family:'Zen Kaku Gothic New',sans-serif;line-height:1.85;-webkit-font-smoothing:antialiased;overflow-x:hidden;}
.rn-maru{font-family:'Zen Maru Gothic',sans-serif;}
.rn-wrap{max-width:680px;margin:0 auto;padding:0 18px 60px;}


.rn-badge{display:inline-flex;align-items:center;gap:7px;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14px;color:#fff;background:var(--navy);border-radius:30px;padding:7px 16px;margin-top:26px;}
.rn-headline{margin-top:16px;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(28px,7.5vw,42px);line-height:1.3;}
.rn-headline .rn-hl{background:linear-gradient(transparent 60%,var(--gold) 60%);padding:0 3px;border-radius:3px;}
.rn-intro{margin-top:14px;font-size:clamp(14.5px,2.6vw,16px);color:var(--ink-2);line-height:1.9;}

.rn-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:26px 0 0;padding:0 0 4px;}
.rn-tabs::-webkit-scrollbar{display:none;}
.rn-tab{flex:0 0 auto;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14px;color:var(--ink-2);background:var(--card);border:2px solid var(--line);border-radius:30px;padding:9px 16px;cursor:pointer;white-space:nowrap;transition:.15s;}
.rn-tab:hover{border-color:var(--navy);}
.rn-tab.rn-on{background:var(--navy);color:#fff;border-color:var(--navy);}

.rn-panel{display:none;animation:rn-fade .35s ease;}
.rn-panel.rn-on{display:block;}
@keyframes rn-fade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

/* クイズ（各タブの先頭） */
.rn-quiz{margin-top:22px;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 8px 24px rgba(31,58,99,.08);}
.rn-quiz .rn-qh{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:16px;margin-bottom:12px;display:flex;gap:8px;align-items:flex-start;line-height:1.45;}.rn-qtx{min-width:0;flex:1;}
.rn-quiz .rn-qh .rn-qd{flex:0 0 24px;width:24px;height:24px;border-radius:50%;background:var(--gold);color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;margin-top:1px;}
.rn-opts{display:flex;flex-direction:column;gap:10px;}
.rn-opt{display:flex;align-items:center;gap:12px;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:16px;color:var(--ink);background:var(--paper);border:2px solid var(--line);border-radius:14px;padding:13px 15px;cursor:pointer;transition:.15s;text-align:left;}
.rn-opt:hover:not(:disabled){border-color:var(--navy);transform:translateY(-1px);}
.rn-opt .rn-k{flex:0 0 28px;width:28px;height:28px;border-radius:50%;background:var(--sky);color:var(--navy);display:flex;align-items:center;justify-content:center;font-size:14px;}
.rn-opt.rn-correct{border-color:var(--green);background:color-mix(in srgb,var(--green) 12%,var(--card));}
.rn-opt.rn-correct .rn-k{background:var(--green);color:#fff;}
.rn-opt.rn-wrong{border-color:#E56A6A;background:color-mix(in srgb,#E56A6A 10%,var(--card));opacity:.75;}
.rn-opt:disabled{cursor:default;}
.rn-answer{display:none;margin-top:14px;padding:18px 16px;background:var(--sky);border-radius:14px;text-align:center;}
.rn-answer.rn-show{display:block;animation:rn-pop .4s ease;}
@keyframes rn-pop{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:scale(1)}}
.rn-answer .rn-rc{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14px;color:var(--green);margin-bottom:8px;}
.rn-answer .rn-title{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(19px,4.8vw,25px);line-height:1.45;color:var(--navy);}
.rn-answer .rn-title .rn-k{color:var(--gold-d);}
.rn-answer .rn-subttl{font-size:13px;color:var(--ink-2);margin-top:8px;}
.rn-answer .rn-lab{font-size:12.5px;color:var(--muted);margin-top:10px;line-height:1.75;}
.rn-answer .rn-lab b{color:var(--ink-2);}

.rn-qsub{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(17px,4.4vw,20px);margin:26px 0 12px;line-height:1.4;}
.rn-hint{font-size:12.5px;color:var(--muted);margin:-4px 0 14px;}

.rn-uses{display:flex;flex-direction:column;gap:10px;}
.rn-use{background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden;}
.rn-use-head{display:flex;align-items:center;gap:11px;padding:13px 14px;cursor:pointer;list-style:none;}
.rn-use-head::-webkit-details-marker{display:none;}
.rn-use-head .rn-em{flex:0 0 34px;width:34px;height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:17px;background:var(--sky);}
.rn-use-head .rn-nm{font-weight:700;font-size:15px;}
.rn-use-head .rn-arw{margin-left:auto;flex:0 0 auto;color:var(--muted);font-size:14px;transition:.2s;}
.rn-use[open] .rn-use-head .rn-arw{transform:rotate(90deg);}
.rn-use-body{padding:0 14px 15px 59px;font-size:13.5px;color:var(--ink-2);line-height:1.85;}
.rn-use-body b{color:var(--ink);}
.rn-lk{color:var(--navy);font-weight:700;}
.rn-mini{margin-top:8px;display:flex;flex-direction:column;gap:5px;}
.rn-mini .rn-m{display:flex;gap:8px;font-size:13px;}
.rn-mini .rn-m .rn-mk{flex:0 0 auto;font-weight:900;color:var(--gold-d);}

.rn-insight{margin-top:16px;background:var(--card);border:1px solid var(--line);border-left:5px solid var(--gold);border-radius:0 14px 14px 0;padding:15px 16px;font-size:13.5px;color:var(--ink-2);line-height:1.85;}
.rn-insight b{color:var(--ink);}

.rn-plans{display:flex;flex-direction:column;gap:11px;margin-top:6px;}
.rn-plan{background:var(--card);border:1px solid var(--line);border-radius:14px;border-left:5px solid var(--pc);padding:14px 16px;}
.rn-plan .rn-ph{display:flex;align-items:center;gap:10px;margin-bottom:5px;}
.rn-plan .rn-pn{flex:0 0 30px;width:30px;height:30px;border-radius:50%;background:var(--pc);color:#fff;display:flex;align-items:center;justify-content:center;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:15px;}
.rn-plan .rn-pl{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:16px;}
.rn-plan .rn-pd{font-size:13px;color:var(--ink-2);line-height:1.8;}
.rn-plan .rn-pd b{color:var(--ink);}
.rn-kushi{margin-top:14px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;}
.rn-kushi .rn-kc{font-size:12.5px;font-weight:700;color:var(--navy);background:var(--sky);border-radius:30px;padding:6px 13px;}

.rn-bld{margin-top:6px;}
.rn-floor{border-radius:14px;padding:16px;margin-bottom:8px;}
.rn-floor .rn-ft{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:13px;margin-bottom:8px;}
.rn-floor.rn-up{background:color-mix(in srgb,var(--gold) 16%,var(--card));border:2px solid var(--gold);}
.rn-floor.rn-up .rn-ft{color:var(--gold-d);}
.rn-floor.rn-up .rn-big{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:clamp(16px,4.2vw,20px);color:var(--ink);line-height:1.4;}
.rn-floor.rn-up .rn-small{font-size:12.5px;color:var(--muted);margin-top:4px;}
.rn-pillars{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;}
.rn-pil{border-radius:12px;padding:14px 8px;text-align:center;color:#fff;}
.rn-pil .rn-pn2{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:14px;line-height:1.35;}
.rn-pil .rn-ps2{font-size:10.5px;opacity:.92;margin-top:4px;}
.rn-floor.rn-base{background:var(--card);border:1px dashed var(--navy);}
.rn-floor.rn-base .rn-ft{color:var(--navy);}
.rn-bld-note{font-size:12.5px;color:var(--ink-2);margin-top:8px;line-height:1.8;text-align:center;}
.rn-bld-note b{color:var(--ink);}
@media(max-width:420px){.rn-pillars{grid-template-columns:1fr;}.rn-pil{padding:11px 13px;text-align:left;display:flex;align-items:baseline;gap:8px;}.rn-pil .rn-ps2{margin-top:0;}}

.rn-region{margin-top:6px;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px;}
.rn-region .rn-rc-center{text-align:center;font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:17px;color:var(--navy);}
.rn-region .rn-rc-town{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:14px;}
.rn-region .rn-tw{font-size:13px;font-weight:700;background:var(--sky);border-radius:12px;padding:8px 13px;}
.rn-region .rn-tw.rn-c{background:var(--navy);color:#fff;}
.rn-rstats{display:flex;gap:10px;margin-top:14px;}
.rn-rstat{flex:1;text-align:center;background:var(--paper);border-radius:12px;padding:12px 8px;}
.rn-rstat .rn-rn{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:19px;color:var(--gold-d);}
.rn-rstat .rn-rl{font-size:11px;color:var(--muted);margin-top:2px;}

/* タブ専用の問いかけ（各タブ末尾に1つ） */
.rn-talk1{margin-top:26px;background:var(--card);border:1px solid var(--line);border-left:5px solid var(--gold);border-radius:0 16px 16px 0;padding:16px 16px 16px 18px;display:flex;gap:12px;align-items:flex-start;}
.rn-talk1 .rn-ic{flex:0 0 auto;font-size:24px;}
.rn-talk1 .rn-tx{font-size:14.5px;color:var(--ink);line-height:1.75;min-width:0;}
.rn-talk1 .rn-tx .rn-lb{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;color:var(--gold-d);font-size:13px;display:block;margin-bottom:3px;}
.rn-talk1 .rn-tx b{font-weight:700;}

.rn-src{margin-top:26px;font-size:11.5px;color:var(--muted);line-height:1.7;}
.rn-sign{margin-top:22px;text-align:center;font-size:12.5px;color:var(--muted);}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;}}


.rn-headline ruby rt,.rn-answer .rn-title ruby rt,.rn-phero .rn-pt ruby rt,.rn-floor.rn-up .rn-big ruby rt{color:var(--navy);}
.rn-term{border-bottom:2px dotted var(--gold-d);cursor:pointer;}
.rn-term-pop{position:fixed;left:12px;right:12px;bottom:14px;margin:0 auto;max-width:520px;background:var(--paper,#fff);border:1.5px solid var(--gold,#c9a24b);color:var(--ink,#333);border-radius:10px;padding:14px 16px 15px;box-shadow:0 6px 22px rgba(0,0,0,.35);z-index:999;font-size:14px;line-height:1.8;animation:rn-pop .3s ease;}
.rn-term-pop .rn-tw{font-family:'Zen Maru Gothic',sans-serif;font-weight:900;font-size:15px;margin-bottom:4px;display:block;}
.rn-term-pop .rn-tw ruby rt{color:var(--muted);}
.rn-term-pop .rn-cl{position:absolute;top:8px;right:12px;cursor:pointer;font-size:18px;opacity:.8;}


