#aikyori{--ak-ink:#22344F;--ak-line:#ece3d2;--ak-card:#fff;--ak-accent:#C2542F;--ak-gold:#E0A93E;--ak-muted:#7c8698}
body.dark #aikyori{--ak-ink:#ece4d6;--ak-line:#2c313d;--ak-card:#1b1f29;--ak-accent:#db6e45;--ak-gold:#eac266;--ak-muted:#8b8577}
#aikyori .ak-intro,#aikyori .ak-foot{font-size:14px;line-height:1.8;color:var(--ak-ink)}
#aikyori .ak-foot{font-size:12.5px;color:var(--ak-muted);margin-top:14px}
#aikyori .ak-total{background:var(--ak-card);border:2px solid var(--ak-gold);border-radius:16px;padding:16px;text-align:center;margin:12px 0}
#aikyori .ak-total .n{font-size:44px;font-weight:900;color:var(--ak-accent);letter-spacing:-1px;line-height:1}
#aikyori .ak-total .u{font-size:14px;color:var(--ak-muted);margin-top:4px}
#aikyori .ak-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:10px 0}
@media(max-width:480px){#aikyori .ak-grid{grid-template-columns:repeat(2,1fr)}}
#aikyori .ak-c{background:var(--ak-card);border:1px solid var(--ak-line);border-radius:12px;padding:10px 8px;text-align:center}
#aikyori .ak-c .ic{font-size:20px}#aikyori .ak-c .v{font-size:22px;font-weight:800;color:var(--ak-ink)}#aikyori .ak-c .v small{font-size:12px;color:var(--ak-muted);font-weight:600}
#aikyori .ak-c .l{font-size:11.5px;color:var(--ak-muted)}
#aikyori .ak-bar{height:6px;background:var(--ak-line);border-radius:3px;margin-top:6px;overflow:hidden}#aikyori .ak-bar i{display:block;height:100%;background:var(--ak-gold)}
#aikyori h3.ak-h{font-size:15px;margin:16px 0 6px;color:var(--ak-ink);border-left:4px solid var(--ak-accent);padding-left:8px}
