#aikyori table.ak-t th,#aikyori table.ak-t td{padding:7px 8px;border-bottom:1px solid var(--ak-line);text-align:left;color:var(--ak-ink)}
#aikyori table.ak-t th{font-size:11.5px;color:var(--ak-muted);font-weight:600}
#aikyori .ak-empty{font-size:13px;color:var(--ak-muted);padding:10px;text-align:center;border:1px dashed var(--ak-line);border-radius:10px}
#aikyori .ak-log{list-style:none;padding:0;margin:0}#aikyori .ak-log li{font-size:13px;padding:6px 0;border-bottom:1px dashed var(--ak-line);color:var(--ak-ink)}#aikyori .ak-log li b{color:var(--ak-accent);margin-right:6px;font-weight:700}


#hg-app{font-size:14px;line-height:1.7}
#hg-app .hg-btn{display:block;width:100%;padding:12px;margin:8px 0;border:none;border-radius:12px;background:var(--navy);color:#fff;font-weight:900;font-size:16px;font-family:inherit;cursor:pointer}
#hg-app .hg-btn:disabled{opacity:.45}
#hg-app .hg-sub{background:var(--card);color:var(--ink);border:2px solid var(--line)}
