#hg-app .hg-side.hg-turn{border-color:#C2542F}
#hg-app .hg-g .hg-t{color:#3b5aa8}#hg-app .hg-h .hg-t{color:#c62828}
#hg-app .hg-t{font-weight:900}
#hg-app .hg-flags{font-size:13px;margin-top:2px}
#hg-app .hg-bar{height:8px;border-radius:4px;background:var(--line);overflow:hidden;margin-top:4px}
#hg-app .hg-bar i{display:block;height:100%}
#hg-app .hg-dice{font-size:46px;text-align:center;line-height:1.1;margin:6px 0}
#hg-app .hg-call{text-align:center;font-weight:900;font-size:20px;color:#C2542F;min-height:1.6em}
#hg-app .hg-msg{text-align:center;font-size:13px;min-height:1.4em}
#hg-app .hg-log{font-size:12px;opacity:.8;max-height:120px;overflow:auto;border-top:1px dashed var(--line);margin-top:6px;padding-top:4px}
#hg-app label{font-size:13px;display:block;text-align:center}
